1	import { db } from "./db";
2	import { MODEL_RATES } from "./models";
3	
4	// ── The anti-bill-shock contract ──────────────────────────────────────────
5	// 1. A credit is a fixed, published amount of real model spend. No mystery units.
6	// 2. We charge from METERED tokens after a build succeeds — never a flat guess.
7	// 3. A build that fails is recorded with its true cost and charged ZERO.
8	// This is Kodely's clearest wedge against the category (see the board's
9	// "credit bill-shock" differentiation cards), so it lives in one small module.
10	
11	/** One credit = $0.002 of underlying model spend (500 credits = $1). */
12	export const MICROS_PER_CREDIT = 2_000;
13	
14	/**
15	 * New accounts start with enough to build and iterate on a real page.
16	 * Sized from measured real costs (2026-08-17): a full first build runs
17	 * ~$0.29 (144 credits), a follow-up edit ~$0.34 (172 credits) on Sonnet 5 —
18	 * 750 covers roughly one build plus 2-3 real edits.
19	 */
20	export const SIGNUP_GRANT = 750;
21	
22	export type Usage = {
23	  inputTokens: number;
24	  outputTokens: number;
25	  cacheReadTokens: number;
26	  cacheWriteTokens: number;
27	};
28	
29	/**
30	 * Micro-dollars of real model spend for a given usage on a given model.
31	 * MODEL_RATES stores USD per MILLION tokens, which — numerically — is
32	 * already USD-per-token expressed in micro-dollars (1e-6 USD = 1 microUSD).
33	 * So `rate * tokens` IS the cost in micros directly; do NOT also divide by
34	 * 1e6, that computes cost in whole dollars instead and silently floors every
35	 * build under $0.50 to 0 (which is exactly the bug this comment replaced —
36	 * caught 2026-08-17 when a real ~$0.22 build was charged only 1 credit).
37	 */
38	export function costMicros(model: string, usage: Usage): number {
39	  const rate = MODEL_RATES[model] ?? MODEL_RATES.default;
40	  const perToken = (perMTok: number, tokens: number) => perMTok * tokens;
41	  return Math.round(
42	    perToken(rate.input, usage.inputTokens) +
43	      perToken(rate.output, usage.outputTokens) +
44	      perToken(rate.cacheRead, usage.cacheReadTokens) +
45	      perToken(rate.cacheWrite, usage.cacheWriteTokens),
46	  );
47	}
48	
49	export function creditsFor(micros: number): number {
50	  return Math.max(1, Math.ceil(micros / MICROS_PER_CREDIT));
51	}
52	
53	export async function getBalance(userId: string): Promise<number> {
54	  const latest = await db.creditLedger.findFirst({
55	    where: { userId },
56	    orderBy: { createdAt: "desc" },
57	  });
58	  return latest?.balanceAfter ?? 0;
59	}
60	
61	export async function grantCredits(userId: string, amount: number, reason: string) {
62	  const balance = await getBalance(userId);
63	  return db.creditLedger.create({
64	    data: { userId, delta: amount, reason, balanceAfter: balance + amount },
65	  });
66	}
67	
68	/**
69	 * Charge for a SUCCESSFUL build. Never call this on a failed build — the whole
70	 * promise to the customer is that broken output is free.
71	 */
72	export async function chargeForBuild(userId: string, buildId: string, credits: number) {
73	  const balance = await getBalance(userId);
74	  await db.creditLedger.create({
75	    data: {
76	      userId,
77	      delta: -credits,
78	      reason: "build",
79	      buildId,
80	      balanceAfter: balance - credits,
81	    },
82	  });
83	  return balance - credits;
84	}
85	
86	/**
87	 * Pre-flight estimate shown BEFORE the user spends anything. Deliberately a
88	 * range derived from observed build sizes, not a fake precise number.
89	 *
90	 * Numbers corrected 2026-08-21. The previous 8-30 / 3-15 ranges predated the
91	 * costMicros fix and understated real spend by roughly an order of magnitude —
92	 * on a product whose headline promise is no bill shock, an estimate that low
93	 * is worse than showing nothing.
94	 *
95	 * The honest state of our evidence: measured builds have come in at ~144
96	 * credits (2026-08-17) and ~472 credits (2026-08-21, a first build of a
97	 * tradesman site via the eval harness). That is a 3x spread across two
98	 * samples, so the range below is deliberately wide rather than falsely
99	 * precise, and skews high — quoting low and charging high is the exact
100	 * failure this whole module exists to prevent.
101	 *
102	 * REPLACE THIS with real percentiles once the eval harness has run a full
103	 * sweep (scripts/eval). Two data points is not a distribution.
104	 */
105	export function estimateCredits(kind: "create" | "edit"): { low: number; high: number } {
106	  return kind === "create" ? { low: 120, high: 550 } : { low: 60, high: 300 };
107	}
108	
109	/**
110	 * Fallback when a user has no build history to average. Sits near the upper
111	 * of our two measurements on purpose: this drives "about N more builds", and
112	 * over-promising remaining builds is how someone hits zero mid-build.
113	 */
114	const TYPICAL_BUILD_CREDITS = 400;
115	
116	/**
117	 * What a build actually costs THIS user, averaged over their recent successful
118	 * builds. Personal history beats a global constant: someone building one-page
119	 * sites and someone building ten-page sites deserve different answers to
120	 * "how many builds do I have left?".
121	 */
122	export async function averageBuildCredits(userId: string): Promise<number> {
123	  const recent = await db.build.findMany({
124	    where: { project: { userId }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
125	    orderBy: { createdAt: "desc" },
126	    take: 10,
127	    select: { creditsCharged: true },
128	  });
129	  if (recent.length === 0) return TYPICAL_BUILD_CREDITS;
130	  const total = recent.reduce((sum, b) => sum + b.creditsCharged, 0);
131	  return Math.max(1, Math.round(total / recent.length));
132	}
133	
134	// ── Self-imposed spend cap ────────────────────────────────────────────────
135	// Point 4 of the anti-bill-shock contract. The three rules above stop us from
136	// OVERCHARGING for a given build; none of them stop a user from running fifty
137	// builds in an afternoon and being genuinely shocked by the total. A ceiling
138	// the user sets themselves is the honest answer, and it is the one guard a
139	// competitor's $607-against-a-$25-plan incident would have needed.
140	//
141	// Rolling 30 days, not calendar month, so there is no "reset day" to game and
142	// no cliff where a cap silently stops protecting someone mid-month.
143	
144	const CAP_WINDOW_DAYS = 30;
145	
146	export type SpendCapStatus = {
147	  /** NULL when the user has set no cap. */
148	  cap: number | null;
149	  spent: number;
150	  /** Credits still available under the cap; Infinity when uncapped. */
151	  remaining: number;
152	  reached: boolean;
153	};
154	
155	/** Credits spent on builds in the rolling window. Grants are excluded. */
156	export async function spentInWindow(userId: string): Promise<number> {
157	  const since = new Date(Date.now() - CAP_WINDOW_DAYS * 24 * 60 * 60 * 1000);
158	  const { _sum } = await db.creditLedger.aggregate({
159	    where: { userId, createdAt: { gte: since }, delta: { lt: 0 } },
160	    _sum: { delta: true },
161	  });
162	  // Deltas are negative for spend; report it as a positive number.
163	  return Math.abs(_sum.delta ?? 0);
164	}
165	
166	export async function getSpendCapStatus(userId: string): Promise<SpendCapStatus> {
167	  const user = await db.user.findUnique({
168	    where: { id: userId },
169	    select: { spendCapCredits: true },
170	  });
171	  const cap = user?.spendCapCredits ?? null;
172	
173	  if (cap === null) {
174	    return { cap: null, spent: 0, remaining: Infinity, reached: false };
175	  }
176	
177	  const spent = await spentInWindow(userId);
178	  return { cap, spent, remaining: Math.max(0, cap - spent), reached: spent >= cap };
179	}
