1	import Anthropic from "@anthropic-ai/sdk";
2	import { MODELS, EFFORT } from "./models";
3	import { narrateTool } from "./build-narration";
4	
5	export type AgentEvent =
6	  | { type: "status"; text: string }
7	  // A live line describing what the agent is doing RIGHT NOW, derived from a
8	  // real tool call (see lib/build-narration.ts). Distinct from "status", which
9	  // marks a phase change the route itself knows about.
10	  | { type: "progress"; text: string }
11	  | { type: "text"; text: string }
12	  | { type: "file"; path: string; action: "write" | "delete" }
13	  | {
14	      type: "usage";
15	      model: string;
16	      inputTokens: number;
17	      outputTokens: number;
18	      cacheReadTokens: number;
19	      cacheWriteTokens: number;
20	    };
21	
22	export type FileMap = Record<string, string>;
23	
24	const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
25	
26	// Generated sites are real Vite + React + TypeScript + Tailwind apps, built
27	// server-side (lib/build-site.ts) into static output served from a
28	// locked-down CSP that blocks every external host — "no CDN, no remote
29	// anything" is a hard constraint rather than a style preference.
30	const SYSTEM = `You are Kodely's site builder. You turn a plain-English description into a real, working website — a genuine Vite + React + TypeScript + Tailwind app, not a static HTML mockup.
31	
32	## The project you're editing
33	Every project starts from a real foundation (package.json, vite.config.ts, tsconfig.json, index.html, src/main.tsx, src/index.css, src/App.tsx, and a few UI primitives under src/components/ui/). You almost never touch the config files — package.json, vite.config.ts, tsconfig.json and src/main.tsx are already correct and there is no way to add a new dependency, so leave them alone unless something is actually broken. Your work happens in \`src/App.tsx\`, new files under \`src/components/\`, and \`src/index.css\`.
34	
35	### index.html — the one config file you MUST edit
36	Every new site needs a real \`<head>\`. The foundation ships a placeholder title and a site is never actually called "Kodely Site" — that title is what shows in the browser tab, in Google, and in every link preview when someone shares the URL. Write, in the site's own language:
37	
38	- \`<title>\` — the real business or site name, with a short qualifier where it helps (e.g. "Bloom Pilates — Reformer studio in Denver"). Under ~60 characters.
39	- \`<meta name="description">\` — one specific sentence about what THIS business offers, ~150 characters. Describe the business, not the template.
40	- \`<meta property="og:title">\` and \`<meta property="og:description">\` — usually the same values; these are what appear when the link is shared.
41	- \`<html lang="...">\` — the correct language if the content is not English.
42	
43	Leave the rest of index.html alone (charset, viewport, the root div, the module script). Never add \`<link>\` or \`<script>\` tags pointing at a remote host — published sites run under a strict CSP that blocks external requests, so they fail silently.
44	
45	## Output contract
46	Use the write_file and delete_file tools. Always pass the complete final file — there is no patch tool.
47	- Build real, composable React components — a Hero, a FeatureGrid, a Footer — not one giant App.tsx.
48	- Style with Tailwind utility classes. The existing primitives (Button, Card, Section, Nav in src/components/ui/) are a starting point — reuse them, extend them, or write new ones as the design calls for, but keep the same quality bar.
49	- Multi-page: this is a single-page app. Build distinct sections/routes as components conditionally rendered or scrolled to, not separate .html files.
50	
51	## Hard constraints — these break the sandboxed build/serve, not just style
52	- NO external requests. No CDN scripts, no Google Fonts, no remote images, no
53	  fetch/XHR to other origins — the CSP blocks all of them at serve time.
54	- Only the dependencies already in package.json exist (react, react-dom). You
55	  cannot add packages — there is no install step per generation.
56	- Images are inline SVG, CSS gradients, or data: URIs. Never <img src="https://...">.
57	- Fonts come from the system stack (ui-sans-serif, -apple-system, "Segoe UI", Inter, sans-serif). No @import, no <link>, and no @font-face — not even with a base64 data: URI. The CSP sets no font-src, so fonts fall back to default-src 'self', which does NOT allow data: (unlike img-src, which does). A base64 font is blocked exactly like a remote one.
58	
59	## Quality bar
60	Ship something that looks designed, not templated. Real, specific copy for the
61	subject at hand — never "Lorem ipsum" and never placeholder headings like
62	"Your Title Here". Responsive down to 380px. Semantic HTML, labelled form
63	controls, sufficient colour contrast, and a visible :focus style. Include a
64	dark-mode treatment unless the brief implies otherwise. Give the page one
65	distinctive visual idea rather than a generic hero-plus-three-cards.
66	
67	## Editing an existing site
68	You are given the current source files. Change only what the request calls
69	for — do not restyle or restructure components the user did not ask about.
70	
71	## Working style
72	Write the files first, then finish with two or three sentences telling the user
73	what you built and what they might want to change next. Do not narrate each file
74	as you write it, and do not paste code into your reply — the user sees a live
75	preview of the result.`;
76	
77	const TOOLS: Anthropic.Tool[] = [
78	  {
79	    name: "write_file",
80	    description:
81	      "Create a file or replace its entire contents. Always pass the complete final file, never a fragment or a diff.",
82	    input_schema: {
83	      type: "object",
84	      properties: {
85	        path: {
86	          type: "string",
87	          description: "Project-relative path, e.g. 'index.html' or 'styles.css'. No leading slash.",
88	        },
89	        content: { type: "string", description: "The complete contents of the file." },
90	      },
91	      required: ["path", "content"],
92	    },
93	  },
94	  {
95	    name: "delete_file",
96	    description: "Delete a file that is no longer part of the site.",
97	    input_schema: {
98	      type: "object",
99	      properties: { path: { type: "string", description: "Project-relative path to delete." } },
100	      required: ["path"],
101	    },
102	  },
103	];
104	
105	/** Reject path traversal and absolute paths before anything touches the DB. */
106	export function normalizePath(raw: string): string | null {
107	  const path = raw.trim().replace(/^\.?\//, "");
108	  if (!path || path.length > 200) return null;
109	  if (path.includes("..") || path.startsWith("/") || path.includes("\\")) return null;
110	  if (!/^[A-Za-z0-9._/-]+$/.test(path)) return null;
111	  return path;
112	}
113	
114	function describeFiles(files: FileMap): string {
115	  const paths = Object.keys(files);
116	  if (paths.length === 0) return "The project is empty — this is the first build.";
117	  return [
118	    "Current files in the project:",
119	    ...paths.map((p) => `\n--- ${p} ---\n${files[p]}`),
120	  ].join("\n");
121	}
122	
123	type RunOptions = {
124	  /** Prior turns, oldest first. */
125	  history: { role: "user" | "assistant"; content: string }[];
126	  request: string;
127	  files: FileMap;
128	  /** First build of a site vs a follow-up tweak — drives how hard we think. */
129	  kind: "create" | "edit";
130	  /** A reference image attached to this turn's request (vision input). */
131	  image?: { mediaType: string; data: string };
132	  /** Applies the write; returning false rejects it (e.g. bad path). */
133	  onWrite: (path: string, content: string) => Promise<boolean>;
134	  onDelete: (path: string) => Promise<boolean>;
135	  /**
136	   * Aborted when the client disconnects (tab closed, network drop). Actually
137	   * cancels the in-flight Anthropic request instead of letting it run to
138	   * completion for nobody — a disconnect shouldn't mean paying full price for
139	   * a generation no one will ever see the result of.
140	   */
141	  signal?: AbortSignal;
142	};
143	
144	/**
145	 * Runs the plan → generate → apply loop, streaming progress as it goes.
146	 * Token usage is accumulated across every turn so the caller can meter the
147	 * true cost of the build (including the repair turns, which we may not bill).
148	 */
149	// Which generation engine to use.
150	//   api (default) — metered Anthropic API via ANTHROPIC_API_KEY. Real cost,
151	//                   real usage telemetry, real credit charges.
152	//   sdk           — Claude Agent SDK on this machine's `claude setup-token`
153	//                   subscription login. No metered spend, so no cost data and
154	//                   0 credits charged. See lib/agent-sdk.ts for the caveats.
155	// Defaults to `api` so a fresh clone never silently runs on someone's personal
156	// subscription; the environment opts in.
157	export const ENGINE = process.env.KODELY_ENGINE === "sdk" ? "sdk" : "api";
158	
159	export async function* runAgent(opts: RunOptions): AsyncGenerator<AgentEvent> {
160	  if (ENGINE === "sdk") {
161	    // Deliberately no try/catch fallback to the API engine: if the SDK is not
162	    // authenticated this must fail loudly rather than quietly spend money on
163	    // the metered key the operator asked not to use.
164	    const { runAgentSdk } = await import("./agent-sdk");
165	    yield* runAgentSdk(opts, SYSTEM);
166	    return;
167	  }
168	
169	  const model = MODELS.builder;
170	  // Effort is the sharpest cost lever we have: a first build is a blank-page
171	  // design problem and earns `high`, while a targeted tweak lands the same
172	  // result at `medium` for a fraction of the thinking tokens.
173	  const effort = opts.kind === "create" ? EFFORT.create : EFFORT.edit;
174	
175	  const messages: Anthropic.MessageParam[] = [];
176	  for (const turn of opts.history) {
177	    messages.push({ role: turn.role, content: turn.content });
178	  }
179	  const requestText = `${describeFiles(opts.files)}\n\n--- Request ---\n${opts.request}`;
180	  if (opts.image) {
181	    messages.push({
182	      role: "user",
183	      content: [
184	        {
185	          type: "image",
186	          source: {
187	            type: "base64",
188	            media_type: opts.image.mediaType as "image/png" | "image/jpeg" | "image/webp",
189	            data: opts.image.data,
190	          },
191	        },
192	        { type: "text", text: `${requestText}\n\n(A reference image is attached above — use it as visual/style guidance for the site.)` },
193	      ],
194	    });
195	  } else {
196	    messages.push({ role: "user", content: requestText });
197	  }
198	
199	  const totals = {
200	    inputTokens: 0,
201	    outputTokens: 0,
202	    cacheReadTokens: 0,
203	    cacheWriteTokens: 0,
204	  };
205	
206	  // Bounded so a confused model can never bill the user for an endless loop.
207	  const MAX_TURNS = 8;
208	
209	  for (let turn = 0; turn < MAX_TURNS; turn++) {
210	    if (opts.signal?.aborted) return;
211	
212	    const stream = anthropic.messages.stream(
213	      {
214	        model,
215	        max_tokens: 32_000,
216	        thinking: { type: "adaptive" },
217	        output_config: { effort },
218	        system: [{ type: "text", text: SYSTEM, cache_control: { type: "ephemeral" } }],
219	        tools: TOOLS,
220	        messages,
221	      },
222	      { signal: opts.signal },
223	    );
224	
225	    for await (const event of stream) {
226	      if (event.type === "content_block_delta" && event.delta.type === "text_delta") {
227	        yield { type: "text", text: event.delta.text };
228	      }
229	    }
230	
231	    const message = await stream.finalMessage();
232	    totals.inputTokens += message.usage.input_tokens ?? 0;
233	    totals.outputTokens += message.usage.output_tokens ?? 0;
234	    totals.cacheReadTokens += message.usage.cache_read_input_tokens ?? 0;
235	    totals.cacheWriteTokens += message.usage.cache_creation_input_tokens ?? 0;
236	
237	    if (message.stop_reason === "refusal") {
238	      throw new Error(
239	        "The request was declined. Try describing the site you want in different terms.",
240	      );
241	    }
242	
243	    const toolUses = message.content.filter(
244	      (b): b is Anthropic.ToolUseBlock => b.type === "tool_use",
245	    );
246	
247	    if (toolUses.length === 0) {
248	      yield { type: "usage", model, ...totals };
249	      return;
250	    }
251	
252	    messages.push({ role: "assistant", content: message.content });
253	
254	    const results: Anthropic.ToolResultBlockParam[] = [];
255	    for (const use of toolUses) {
256	      const input = use.input as { path?: string; content?: string };
257	      const path = normalizePath(input.path ?? "");
258	
259	      if (!path) {
260	        results.push({
261	          type: "tool_result",
262	          tool_use_id: use.id,
263	          content: `Rejected: '${input.path}' is not a valid project-relative path.`,
264	          is_error: true,
265	        });
266	        continue;
267	      }
268	
269	      // Narrate before applying, so the line appears while the write is
270	      // happening rather than after it lands.
271	      const line = narrateTool(use.name, { path });
272	      if (line) yield { type: "progress", text: line };
273	
274	      if (use.name === "write_file") {
275	        const ok = await opts.onWrite(path, input.content ?? "");
276	        if (ok) yield { type: "file", path, action: "write" };
277	        results.push({
278	          type: "tool_result",
279	          tool_use_id: use.id,
280	          content: ok ? `Wrote ${path}.` : `Could not write ${path}.`,
281	          is_error: !ok,
282	        });
283	      } else if (use.name === "delete_file") {
284	        const ok = await opts.onDelete(path);
285	        if (ok) yield { type: "file", path, action: "delete" };
286	        results.push({
287	          type: "tool_result",
288	          tool_use_id: use.id,
289	          content: ok ? `Deleted ${path}.` : `${path} did not exist.`,
290	          is_error: false,
291	        });
292	      } else {
293	        results.push({
294	          type: "tool_result",
295	          tool_use_id: use.id,
296	          content: `Unknown tool ${use.name}.`,
297	          is_error: true,
298	        });
299	      }
300	    }
301	
302	    messages.push({ role: "user", content: results });
303	  }
304	
305	  yield { type: "usage", model, ...totals };
306	}
