87	type Rendered = Pick<AssetMatch, "format" | "source" | "usage" | "variants">;
88	
89	type Entry = {
90	  id: string;
91	  kind: AssetKind;
92	  name: string;
93	  /** Lowercased, de-duplicated search terms. */
94	  keywords: string[];
95	  render: (opts: FindAssetsOptions) => Rendered;
96	};
97	
98	function iconEntry(icon: Icon): Entry {
99	  return {
100	    id: `icon:${icon.id}`,
101	    kind: "icon",
102	    name: icon.name,
103	    keywords: icon.keywords,
104	    render: (opts) => ({
105	      format: "jsx",
106	      source: iconJsx(icon.id, { weight: opts.weight ?? "regular", size: null, className: "h-6 w-6" }) ?? "",
107	      usage:
108	        "Paste inline into a .tsx file. Stroke is currentColor, so set the colour with a Tailwind text-* class on the icon or its parent; size with h-*/w-*.",
109	      variants: {
110	        svg: iconSvg(icon.id, { weight: opts.weight ?? "regular" }) ?? "",
111	        dataUri: iconDataUri(icon.id, { weight: opts.weight ?? "regular" }) ?? "",
112	        category: icon.category,
113	      },
114	    }),
115	  };
116	}
117	
118	function flagEntry(flag: Flag): Entry {
119	  const kw = [
120	    flag.code,
121	    ...flag.name.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean),
122	    "flag",
123	    "country",
124	    "nation",
125	    ...(flag.svg ? ["svg"] : ["emoji"]),
126	  ];
127	  return {
128	    id: `flag:${flag.code}`,
129	    kind: "flag",
130	    name: flag.name,
131	    keywords: kw,
132	    render: (): Rendered => {
133	      const svg = flag.svg ? flagSvg(flag.code, { width: 60 }) : null;
134	      if (svg) {
135	        return {
136	          format: "jsx",
137	          source: toJsx(svg),
138	          usage:
139	            flag.svg?.accuracy === "simplified"
140	              ? `Hand-authored SVG, JSX-ready. SIMPLIFIED: ${flag.svg.note ?? "detail omitted"} — use the emoji instead if exactness matters.`
141	              : "Hand-authored SVG, JSX-ready and accurate to the flag's construction. Paste inline into a .tsx file.",
142	          variants: { emoji: flag.emoji, code: flag.code, accuracy: flag.svg?.accuracy ?? "", svg },
143	        };
144	      }
145	      return {
146	        format: "text",
147	        source: flag.emoji,
148	        usage:
149	          "Emoji flag — plain text, works with no asset at all. Note that Windows Chrome/Edge render these as two letter boxes, not a flag.",
150	        variants: { code: flag.code },
151	      };
152	    },
153	  };
154	}
