374	const STOPWORDS = new Set(["a", "an", "the", "of", "for", "and", "or", "to", "in", "on", "icon", "icons"]);
375	
376	function tokenize(query: string): string[] {
377	  return query
378	    .toLowerCase()
379	    .split(/[^a-z0-9]+/)
380	    .filter((t) => t.length > 0 && !STOPWORDS.has(t));
381	}
382	
383	/** How well one query token matches one asset. 0 means "not at all". */
384	function tokenScore(entry: Entry, token: string, isSynonym: boolean): number {
385	  const bare = entry.id.slice(entry.id.indexOf(":") + 1);
386	  let best = 0;
387	  if (bare === token) best = 16;
388	  else if (entry.name.toLowerCase() === token) best = 14;
389	  else {
390	    for (const kw of entry.keywords) {
391	      if (kw === token) best = Math.max(best, 10);
392	      else if (token.length >= 3 && kw.startsWith(token)) best = Math.max(best, 6);
393	      else if (token.length >= 4 && kw.includes(token)) best = Math.max(best, 3);
394	      if (best === 10) break;
395	    }
396	    if (best === 0 && token.length >= 4 && bare.includes(token)) best = 4;
397	  }
398	  // A synonym hit is real but weaker than the word the caller actually typed.
399	  return isSynonym ? best * 0.6 : best;
400	}
401	
402	function kindFilter(kind: FindAssetsOptions["kind"]): Set<AssetKind> | null {
403	  if (!kind) return null;
404	  const list = Array.isArray(kind) ? kind : [kind];
405	  const valid = list.filter((k): k is AssetKind => ASSET_KINDS.includes(k));
406	  return valid.length > 0 ? new Set(valid) : null;
407	}
408	
409	function toMatch(entry: Entry, score: number, opts: FindAssetsOptions): AssetMatch {
410	  const rendered = entry.render(opts);
411	  return { id: entry.id, kind: entry.kind, name: entry.name, keywords: entry.keywords, score, ...rendered };
412	}
