414	/**
415	 * Keyword/synonym search across icons, flags, gradients, meshes, textures,
416	 * dividers, patterns and avatars.
417	 *
418	 * Multi-word queries are AND-ish: every token must contribute something, so
419	 * "coffee shop" prefers assets that speak to both rather than everything that
420	 * mentions "shop". An empty query lists the catalogue (filtered by `kind`).
421	 */
422	export function findAssets(query: string, opts: FindAssetsOptions = {}): AssetMatch[] {
423	  const limit = Math.min(Math.max(opts.limit ?? 20, 1), 100);
424	  const allowed = kindFilter(opts.kind);
425	  const pool = allowed ? CATALOG.filter((e) => allowed.has(e.kind)) : CATALOG;
426	
427	  const tokens = tokenize(query);
428	  if (tokens.length === 0) return pool.slice(0, limit).map((e) => toMatch(e, 0, opts));
429	
430	  const scored: { entry: Entry; score: number }[] = [];
431	  for (const entry of pool) {
432	    let total = 0;
433	    let missed = false;
434	    for (const token of tokens) {
435	      let best = tokenScore(entry, token, false);
436	      if (best === 0) {
437	        for (const syn of SYNONYMS[token] ?? []) {
438	          best = Math.max(best, tokenScore(entry, syn, true));
439	        }
440	      }
441	      if (best === 0) {
442	        missed = true;
443	        break;
444	      }
445	      total += best;
446	    }
447	    // A single-token query is a browse, not a filter, so a partial hit still
448	    // counts. Multi-token queries require every token to land.
449	    if (!missed && total > 0) scored.push({ entry, score: total });
450	  }
451	
452	  scored.sort((a, b) => b.score - a.score || a.entry.id.localeCompare(b.entry.id));
453	  return scored.slice(0, limit).map(({ entry, score }) => toMatch(entry, score, opts));
454	}
