456	/** Look one asset up by its stable id, e.g. "icon:phone". */
457	export function getAsset(id: string, opts: FindAssetsOptions = {}): AssetMatch | null {
458	  const entry = BY_ID.get(id.trim());
459	  return entry ? toMatch(entry, 0, opts) : null;
460	}
