462	/** Everything, optionally of one kind. Ordered as declared. */
463	export function listAssets(kind?: AssetKind, opts: FindAssetsOptions = {}): AssetMatch[] {
464	  const pool = kind ? CATALOG.filter((e) => e.kind === kind) : CATALOG;
465	  return pool.map((e) => toMatch(e, 0, opts));
466	}
