468	/** Ids only — cheap enough to put in a prompt or a picker's index. */
469	export function listAssetIds(kind?: AssetKind): string[] {
470	  return (kind ? CATALOG.filter((e) => e.kind === kind) : CATALOG).map((e) => e.id);
471	}
