1	// SEO for PUBLISHED sites (served by app/api/site/[slug]/...).
2	//
3	// Why any of this exists at serve time rather than purely in generation:
4	// the builder prompt is told to fill in index.html's <head>, but a prompt is
5	// guidance, not a guarantee. Everything here is a backstop that runs on the
6	// way out, so a site can never be published with the foundation's placeholder
7	// title — which is exactly what shipped before (every site was "Kodely Site",
8	// in the browser tab, in Google, and in every link preview).
9	//
10	// It also fixes ALREADY-published sites with no regeneration, because it
11	// rewrites on read rather than at build time.
12	
13	const SITES_BASE = process.env.KODELY_SITES_BASE ?? "kodely.site";
14	
15	// The foundation's placeholder. If this survives to serve time the agent
16	// didn't personalise the head, so we substitute the real project name.
17	const PLACEHOLDER_TITLE = "Kodely Site";
18	
19	/**
20	 * Public base URL of a published site, as a visitor sees it.
21	 *
22	 * Two shapes, because the proxy rewrites the branded subdomain onto an
23	 * internal path:
24	 *   <slug>.kodely.site/         -> internally /api/site/<slug>
25	 *   staging.kodely.me/api/site/<slug>/   (no wildcard DNS off prod)
26	 *
27	 * Canonical/OG URLs must use the EXTERNAL form or they point somewhere the
28	 * visitor's browser never went, so this keys off the Host header.
29	 */
30	export function siteBaseUrl(req: Request, slug: string): string {
31	  const host = req.headers.get("host") ?? "";
32	  const bare = host.split(":")[0];
33	
34	  // Deliberately NOT derived from x-forwarded-proto. Cloudflare's SSL mode
35	  // here is Flexible: it terminates TLS at the edge and talks to the origin
36	  // over plain HTTP, so nginx forwards `x-forwarded-proto: http` even though
37	  // the visitor is on https. Trusting it emitted http:// canonical and og:url
38	  // on sites that are only reachable over https.
39	  //
40	  // That was invisible in testing because Cloudflare's Automatic HTTPS
41	  // Rewrites silently repairs href="http://..." (canonical) but NOT
42	  // content="http://..." (og:url) — so only the OG tag stayed wrong, and
43	  // only when checked through the real edge.
44	  //
45	  // Every published site is reachable only via the Cloudflare HTTPS edge, so
46	  // anything that isn't loopback is https by definition.
47	  const isLocal = bare === "localhost" || bare === "127.0.0.1" || bare === "::1";
48	  const proto = isLocal ? "http" : "https";
49	  // Branded subdomain: the site lives at the host root.
50	  if (bare.endsWith(`.${SITES_BASE}`)) return `${proto}://${host}`;
51	  // Otherwise it is served under a path (staging, localhost).
52	  return `${proto}://${host}/api/site/${slug}`;
53	}
54	
55	function escapeHtml(s: string): string {
56	  return s
57	    .replace(/&/g, "&amp;")
58	    .replace(/</g, "&lt;")
59	    .replace(/>/g, "&gt;")
60	    .replace(/"/g, "&quot;");
61	}
62	
63	function escapeXml(s: string): string {
64	  return escapeHtml(s).replace(/'/g, "&apos;");
65	}
66	
67	/** Absolutise a root-relative URL against the site's public base. */
68	function absolutise(value: string, base: string): string {
69	  if (/^https?:\/\//i.test(value) || value.startsWith("data:")) return value;
70	  return `${base.replace(/\/$/, "")}/${value.replace(/^\//, "")}`;
71	}
72	
73	/**
74	 * Ensure a served HTML document has a real title, a description, canonical
75	 * and OG/Twitter tags. Only fills gaps — anything the builder already wrote
76	 * is left exactly as-is, since it had the site's actual content in view and
77	 * this function does not.
78	 */
79	export function applySeo(html: string, opts: { projectName: string; baseUrl: string }): string {
80	  const { projectName, baseUrl } = opts;
81	  if (!/<head[\s>]/i.test(html)) return html; // not a full document; leave alone
82	
83	  let out = html;
84	
85	  // 1. Title — replace the placeholder, or add one if missing entirely.
86	  const titleMatch = out.match(/<title>([\s\S]*?)<\/title>/i);
87	  const currentTitle = titleMatch?.[1]?.trim();
88	  const title = !currentTitle || currentTitle === PLACEHOLDER_TITLE ? projectName : currentTitle;
89	  if (titleMatch) {
90	    if (currentTitle !== title) {
91	      out = out.replace(/<title>[\s\S]*?<\/title>/i, `<title>${escapeHtml(title)}</title>`);
92	    }
93	  } else {
94	    out = out.replace(/<head([^>]*)>/i, `<head$1>\n    <title>${escapeHtml(title)}</title>`);
95	  }
96	
97	  const inject: string[] = [];
98	
99	  // Upsert a <meta>/<link>: fill it when the tag is absent OR present with an
100	  // empty value. The foundation ships empty `content=""` scaffolding to show
101	  // the builder what to write, so "tag exists" alone is not good enough — an
102	  // existence-only check would leave those empty forever.
103	  const upsert = (attrRe: RegExp, valueAttr: "content" | "href", value: string, tag: string) => {
104	    const existing = out.match(attrRe);
105	    if (!existing) {
106	      inject.push(tag);
107	      return;
108	    }
109	    const valRe = new RegExp(`${valueAttr}=["']([^"']*)["']`, "i");
110	    const current = existing[0].match(valRe)?.[1];
111	    if (current === undefined || current.trim() === "") {
112	      out = out.replace(existing[0], tag);
113	    }
114	  };
115	
116	  const desc = `${title} — built with Kodely.`;
117	  upsert(
118	    /<meta\s+name=["']description["'][^>]*>/i,
119	    "content",
120	    desc,
121	    `<meta name="description" content="${escapeHtml(desc)}" />`,
122	  );
123	  upsert(
124	    /<link\s+rel=["']canonical["'][^>]*>/i,
125	    "href",
126	    baseUrl,
127	    `<link rel="canonical" href="${escapeHtml(baseUrl)}" />`,
128	  );
129	  upsert(
130	    /<meta\s+property=["']og:title["'][^>]*>/i,
131	    "content",
132	    title,
133	    `<meta property="og:title" content="${escapeHtml(title)}" />`,
134	  );
135	  upsert(
136	    /<meta\s+property=["']og:description["'][^>]*>/i,
137	    "content",
138	    desc,
139	    `<meta property="og:description" content="${escapeHtml(desc)}" />`,
140	  );
141	  upsert(
142	    /<meta\s+property=["']og:type["'][^>]*>/i,
143	    "content",
144	    "website",
145	    `<meta property="og:type" content="website" />`,
146	  );
147	  upsert(
148	    /<meta\s+property=["']og:url["'][^>]*>/i,
149	    "content",
150	    baseUrl,
151	    `<meta property="og:url" content="${escapeHtml(baseUrl)}" />`,
152	  );
153	  upsert(
154	    /<meta\s+name=["']twitter:card["'][^>]*>/i,
155	    "content",
156	    "summary_large_image",
157	    `<meta name="twitter:card" content="summary_large_image" />`,
158	  );
159	
160	  if (inject.length) {
161	    out = out.replace(/<\/head>/i, `  ${inject.join("\n    ")}\n  </head>`);
162	  }
163	
164	  // Crawlers reject relative og:image, so absolutise whatever the builder set.
165	  out = out.replace(
166	    /(<meta\s+property=["']og:image["']\s+content=["'])([^"']+)(["'])/gi,
167	    (_m, pre, url, post) => `${pre}${escapeHtml(absolutise(url, baseUrl))}${post}`,
168	  );
169	
170	  return out;
171	}
172	
173	/** robots.txt pointing crawlers at the sitemap. Generated, never stored. */
174	export function robotsTxt(baseUrl: string): string {
175	  return `User-agent: *\nAllow: /\n\nSitemap: ${baseUrl.replace(/\/$/, "")}/sitemap.xml\n`;
176	}
177	
178	/**
179	 * sitemap.xml from the site's published HTML files. Generated per request so
180	 * it can use the visitor-facing host and can never drift from what is served.
181	 */
182	export function sitemapXml(baseUrl: string, htmlPaths: string[], lastMod?: Date): string {
183	  const base = baseUrl.replace(/\/$/, "");
184	  const seen = new Set<string>();
185	  const urls = htmlPaths
186	    .map((p) => (p === "index.html" ? "" : `/${p.replace(/^\//, "")}`))
187	    .filter((u) => (seen.has(u) ? false : (seen.add(u), true)))
188	    .map((u) => {
189	      const loc = escapeXml(base + u);
190	      const mod = lastMod ? `\n    <lastmod>${lastMod.toISOString().slice(0, 10)}</lastmod>` : "";
191	      return `  <url>\n    <loc>${loc}</loc>${mod}\n  </url>`;
192	    })
193	    .join("\n");
194	  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls}\n</urlset>\n`;
195	}
