132	      // Declared out here so the catch below can record it too.
133	      let repairAttempts = 0;
134	      const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
135	      let model = "";
136	      let lastReply = "";
137	      let lastProgress = "";
138	
139	      const readSourceFiles = async (): Promise<FileMap> => {
140	        const rows = await db.projectFile.findMany({
141	          where: { projectId: project.id, published: false, kind: "source" },
142	        });
143	        return Object.fromEntries(rows.map((f) => [f.path, f.content]));
144	      };
145	
146	      try {
147	        let request = prompt;
148	        let buildOutput: FileMap | null = null;
149	        let lastBuildError = "";
150	
151	        for (let attempt = 1; attempt <= MAX_BUILD_ATTEMPTS; attempt++) {
152	          if (abortController.signal.aborted) break;
153	
154	          const generator = runAgent({
155	            history: project.messages.map((m) => ({
156	              role: m.role === "assistant" ? ("assistant" as const) : ("user" as const),
157	              content: m.content,
158	            })),
159	            request,
160	            files: await readSourceFiles(),
161	            kind,
162	            // Only attached on the very first turn of a project — a repair
163	            // retry re-sends the same `request` text but should not attach
164	            // the image again mid-loop.
165	            image: attempt === 1 ? image : undefined,
166	            signal: abortController.signal,
167	            onWrite: async (path, content) => {
168	              if (!normalizePath(path)) return false;
169	              await db.projectFile.upsert({
170	                where: {
171	                  projectId_path_published_kind: {
172	                    projectId: project.id,
173	                    path,
174	                    published: false,
175	                    kind: "source",
176	                  },
177	                },
178	                create: { projectId: project.id, path, content, published: false, kind: "source" },
179	                update: { content },
180	              });
181	              filesWritten++;
182	              return true;
183	            },
184	            onDelete: async (path) => {
185	              const { count } = await db.projectFile.deleteMany({
186	                where: { projectId: project.id, path, published: false, kind: "source" },
187	              });
188	              return count > 0;
189	            },
190	          });
191	
192	          for await (const event of generator) {
193	            if (event.type === "text") {
194	              lastReply += event.text;
195	              send(event);
196	            } else if (event.type === "file") {
197	              send(event);
198	            } else if (event.type === "status") {
199	              send(event);
200	            } else if (event.type === "progress") {
201	              // Collapse consecutive identical lines. A run of twelve Reads
202	              // narrates as one "Looking through the project" rather than
203	              // twelve, which would read as a stutter rather than progress.
204	              if (event.text !== lastProgress) {
205	                lastProgress = event.text;
206	                send(event);
207	              }
208	            } else if (event.type === "usage") {
209	              model = event.model;
210	              totals.inputTokens += event.inputTokens;
211	              totals.outputTokens += event.outputTokens;
212	              totals.cacheReadTokens += event.cacheReadTokens;
213	              totals.cacheWriteTokens += event.cacheWriteTokens;
214	            }
215	          }
216	
217	          if (abortController.signal.aborted) break;
218	
219	          try {
220	            send({ type: "progress", text: "Compiling the site" });
221	            buildOutput = await buildSite(await readSourceFiles());
222	            break; // compiled cleanly — done
223	          } catch (err) {
224	            lastBuildError = err instanceof BuildError ? err.message : String(err);
225	            if (attempt >= MAX_BUILD_ATTEMPTS) throw new Error(lastBuildError);
226	            repairAttempts++;
227	            // Clear the dedupe key: the repair pass legitimately repeats the
228	            // same lines, and suppressing them would look like a stall.
229	            lastProgress = "";
230	            send({ type: "status", text: "Build didn't compile — fixing it…" });
231	            request = `The last change failed to build. Fix it and keep the rest of the change. Build error:\n${lastBuildError}`;
232	          }
233	        }
234	
235	        if (abortController.signal.aborted || !buildOutput) {
236	          // Loop ended without a successful build and without throwing —
237	          // only reachable via the abort path (see the `break` above).
238	        } else {
239	          succeeded = true;
240	
241	          // Replace the compiled tree with the new build output.
242	          await db.$transaction([
243	            db.projectFile.deleteMany({ where: { projectId: project.id, published: false, kind: "build" } }),
244	            ...(Object.keys(buildOutput).length > 0
245	              ? [
246	                  db.projectFile.createMany({
247	                    data: Object.entries(buildOutput).map(([path, content]) => ({
248	                      projectId: project.id,
249	                      path,
250	                      content,
251	                      published: false,
252	                      kind: "build",
253	                    })),
254	                  }),
255	                ]
256	              : []),
257	          ]);
258	
259	          const micros = costMicros(model, totals);
260	          const credits = creditsFor(micros);
261	          const remaining = await chargeForBuild(user.id, build.id, credits);
262	
263	          const sourceFiles = await readSourceFiles();
264	          const filesSnapshot = { source: sourceFiles, build: buildOutput };
265	
266	          await db.build.update({
267	            where: { id: build.id },
268	            data: {
269	              status: "SUCCEEDED",
270	              model,
271	              endedAt: new Date(),
272	              inputTokens: totals.inputTokens,
273	              outputTokens: totals.outputTokens,
274	              cacheReadTokens: totals.cacheReadTokens,
275	              cacheWriteTokens: totals.cacheWriteTokens,
276	              filesWritten,
277	              repairAttempts,
278	              costMicros: micros,
279	              creditsCharged: credits,
280	              filesSnapshot,
281	            },
282	          });
283	
284	          track(EVENTS.buildSucceeded, {
285	            userId: user.id,
286	            props: {
287	              buildId: build.id,
288	              projectId: project.id,
289	              kind,
290	              model,
291	              repairAttempts,
292	              filesWritten,
293	              credits,
294	              remaining,
295	            },
296	          });
297	
298	          if (lastReply.trim()) {
299	            await db.message.create({
300	              data: { projectId: project.id, role: "assistant", content: lastReply.trim() },
301	            });
302	          }
303	          await db.project.update({ where: { id: project.id }, data: { updatedAt: new Date() } });
304	
305	          // buildId travels to the client so it can attach a rating to this
306	          // specific build (see app/api/feedback/route.ts).
307	          send({ type: "done", credits, remaining, filesWritten, buildId: build.id });
308	        }
309	
310	        if (!succeeded) {
311	          await db.build.update({
312	            where: { id: build.id },
313	            data: {
314	              status: "FAILED",
315	              endedAt: new Date(),
316	              error: abortController.signal.aborted ? "Client disconnected." : "Generation ended without producing output.",
317	              filesWritten,
318	              repairAttempts,
319	              creditsCharged: 0,
320	            },
321	          });
322	
323	          track(EVENTS.buildFailed, {
324	            userId: user.id,
325	            props: {
326	              buildId: build.id,
327	              projectId: project.id,
328	              kind,
329	              repairAttempts,
330	              reason: abortController.signal.aborted ? "aborted" : "no_output",
331	            },
332	          });
333	        }
334	      } catch (error) {
335	        // A build that fails is never charged — that is the product promise,
336	        // so the ledger is deliberately untouched on this path.
337	        const message =
338	          error instanceof Error ? error.message : "The build failed unexpectedly.";
339	        console.error("[kodely] build failed", build.id, error);
340	
341	        await db.build.update({
342	          where: { id: build.id },
343	          data: {
344	            status: "FAILED",
345	            endedAt: new Date(),
346	            error: message.slice(0, 1000),
347	            filesWritten,
348	            repairAttempts,
349	            creditsCharged: 0,
350	          },
351	        });
352	
353	        track(EVENTS.buildFailed, {
354	          userId: user.id,
355	          props: {
356	            buildId: build.id,
357	            projectId: project.id,
358	            kind,
359	            repairAttempts,
360	            reason: "error",
361	          },
362	        });
363	
364	        send({ type: "error", message });
365	      } finally {
366	        try {
367	          controller.close();
368	        } catch {
369	          // already closed by the client disconnect path
370	        }
371	      }
372	    },
373	    cancel() {
374	      // The client disconnected — stop the in-flight Anthropic request
375	      // rather than let it run to completion for a response nobody reads.
376	      abortController.abort();
377	    },
378	  });
379	
380	  return new Response(stream, {
381	    headers: {
382	      "Content-Type": "text/event-stream; charset=utf-8",
383	      "Cache-Control": "no-cache, no-transform",
384	      Connection: "keep-alive",
385	    },
386	  });
387	}
